export function LipTagIcon({ sprite, className, size = 16 }: { sprite: LipTagSprite; className?: string; size?: number }) {
  const data = LIP_TAG_SPRITES[sprite];
  if (!data) return null;
  return (
    <svg
      xmlns="http://www.w3.org/2000/svg"
      viewBox="0 0 16 16"
      width={size}
      height={size}
      shapeRendering="crispEdges"
      aria-hidden="true"
      focusable="false"
      className={cn("shrink-0", className)}
    >
      {data.layers.map(([fill, d]) => (
        <path key={fill} fill={fill} d={d} />
      ))}
    </svg>
  );
}
